CREATE TABLE entries (key TEXT PRIMARY KEY, kind TEXT NOT NULL, head TEXT NOT NULL);
CREATE TABLE links (src TEXT NOT NULL, relation TEXT NOT NULL, dst TEXT NOT NULL, dst_revision TEXT NOT NULL,
  note TEXT, PRIMARY KEY (src, relation, dst));
CREATE TABLE revisions (id TEXT PRIMARY KEY, key TEXT NOT NULL, body TEXT NOT NULL, digest TEXT NOT NULL,
  actor TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX revisions_key ON revisions(key, at);
CREATE INDEX links_dst ON links(dst, relation);
